#!/usr/bin/env python3
"""
Garante os ícones mínimos obrigatórios do ODC Studio Tauri antes do cargo build.

Motivação:
- tauri::generate_context!() exige icons/icon.png em Linux/macOS;
- tauri-build exige icons/icon.ico no Windows para o resource file;
- este script torna o build autossuficiente mesmo se os binários não estiverem
  versionados no checkout.

Os bytes são fixos e verificados por SHA-256 antes de serem gravados.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ICONS_DIR = ROOT / "rust-tauri" / "studio" / "src-tauri" / "icons"

ASSETS = {
    "icon.png": {
        "sha256": "2eaf8b8390e510a91e586b08e32d97c73835e2aa838e8fbf4fd0298db6247982",
        "base64": """""",
    },
    "icon.ico": {
        "sha256": "b9e182383c124b4c457840b1ed5a7123fbc25cbaf8521a99771c43d567ba06b5",
        "base64": """""",
    },
}

def decode_asset(name: str, item: dict[str, str]) -> bytes:
    data = base64.b64decode(item["base64"], validate=True)
    actual = hashlib.sha256(data).hexdigest()
    if actual != item["sha256"]:
        raise RuntimeError(
            f"Payload embutido corrompido para {name}: "
            f"esperado={item['sha256']} atual={actual}"
        )
    return data

def verify_file(path: Path, expected_sha: str) -> bool:
    if not path.is_file() or path.stat().st_size == 0:
        return False
    return hashlib.sha256(path.read_bytes()).hexdigest() == expected_sha

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--check",
        action="store_true",
        help="Apenas valida payloads embutidos e, se existirem, os arquivos em disco.",
    )
    args = parser.parse_args()

    decoded = {name: decode_asset(name, item) for name, item in ASSETS.items()}

    if args.check:
        for name, item in ASSETS.items():
            path = ICONS_DIR / name
            if path.exists() and not verify_file(path, item["sha256"]):
                raise RuntimeError(f"Ícone existente inválido: {path}")
        print("Payloads dos ícones Tauri validados.")
        return 0

    ICONS_DIR.mkdir(parents=True, exist_ok=True)

    for name, data in decoded.items():
        path = ICONS_DIR / name
        expected = ASSETS[name]["sha256"]

        if verify_file(path, expected):
            print(f"OK {path}")
            continue

        path.write_bytes(data)

        if not verify_file(path, expected):
            raise RuntimeError(f"Falha ao materializar ícone válido: {path}")

        print(f"Gerado {path}")

    return 0

if __name__ == "__main__":
    raise SystemExit(main())
